cases.bad:
// show path
video.style.setProperty('transform', 'translate(-50%, -50%)', 'important');
video.style.setProperty('object-fit', 'contain', 'important');
// hide path — removes position/left/top/width but NOT transform/object-fit
video.style.removeProperty('position');
video.style.removeProperty('left');
video.style.removeProperty('top');
// transform: translate(-50%,-50%) !important persists → video shifted off-screen

cases.good:
// hide path must clear every prop the show path set with !important
video.style.removeProperty('transform');
video.style.setProperty('object-fit', 'contain', 'important'); // keep contain, not cover
// If a MutationObserver guard re-applies styles, stop it FIRST:
this.styleGuard?.disconnect();
video.style.removeProperty('transform');

cases.bad:
// createPanel (floating mode)
panelBody.style.maxHeight = '400px';
// showPanelDocked — does not touch maxHeight → 400px cap persists into docked mode
// docked panel container is height:100% but body capped → empty space below cue list

cases.good:
// showPanelDocked — reset mode-specific style for the new mode
panelBody.style.maxHeight = 'none'; // fill docked panel
// hidePanelDocked — restore the floating-mode value
panelBody.style.maxHeight = '400px';
